 let drag=-1;v.querySelectorAll('.ew-sec').forEach(r=>{r.ondragstart=e=>{drag=+r.dataset.i;e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',String(drag))}catch(_){}};r.ondragover=e=>e.preventDefault();r.ondrop=e=>{e.preventDefault();if(drag>=0&&drag!==+r.dataset.i)mv(drag,+r.dataset.i);drag=-1}});
 v.querySelectorAll('[data-ft]').forEach(c=>c.onchange=()=>act(async()=>{const z=await db.from('events').update({featured:c.checked,featured_order:c.checked?feat.length+1:0}).eq('id',c.dataset.ft).select('id');if(z.error)throw z.error;if(!z.data.length)throw new Error('Not updated.')},'Featured selection updated (this applies to the live page straight away).',async()=>{await load('ev',1);SEC.design(v)}));
 const fmv=(i,j)=>{if(j<0||j>=feat.length)return;const a=feat.slice(),[x]=a.splice(i,1);a.splice(j,0,x);act(async()=>{for(let n=0;n<a.length;n++){const z=await db.from('events').update({featured_order:n+1}).eq('id',a[n].id).select('id');if(z.error)throw z.error}},'Order saved.',async()=>{await load('ev',1);SEC.design(v)})};
 v.querySelectorAll('[data-fu]').forEach(b=>b.onclick=()=>fmv(+b.dataset.fu,+b.dataset.fu-1));v.querySelectorAll('[data-fd]').forEach(b=>b.onclick=()=>fmv(+b.dataset.fd,+b.dataset.fd+1));
 $('hi').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!imgOk(f))return say('Hero image must be JPG, PNG or WebP.',1);try{S.cfg.hero.image=await upload('gallery-media',f,10);S.dirty=1;SEC.design(v)}catch(x){say(x.message,1)}};const hx=$('hi-x');if(hx)hx.onclick=()=>{S.cfg.hero.image='';S.dirty=1;SEC.design(v)};
